/* The Fairy Woods picture: the scene itself. It is drawn onto the backdrop layer (see vs_wood_forest.js); creatures and the menu mushrooms live on top of it. */
(() => { const im = new Image(); im.onload = () => { window.__WOODPIC = im; if (window.__needPic) { window.__needPic = false; setTimeout(() => window.dispatchEvent(new Event('resize')), 60); } }; im.src = 'data:image/jpeg;base64,'; })();
